const keys=["revenue","cost","expenses","companyCash","personalCash","familyAssets","investments","receivable","overdue","inventory","fixedAssets","companyDebt","personalDebt","incoming30","outgoing30","monthlyFixed"];
const json=(body,status=200)=>new Response(JSON.stringify(body),{status,headers:{"content-type":"application/json; charset=utf-8","cache-control":"no-store"}});
function user(request){const id=request.headers.get("oai-authenticated-user-id"),email=request.headers.get("oai-authenticated-user-email");if(!id||!email)return null;let name=email.split("@")[0];const encoded=request.headers.get("oai-authenticated-user-full-name");if(encoded&&request.headers.get("oai-authenticated-user-full-name-encoding")==="percent-encoded-utf-8"){try{name=decodeURIComponent(encoded)}catch{}}return{id,email,name}}
function cleanData(input){if(!input||typeof input!=="object")throw new Error("缺少财务数据");const result={};for(const key of keys){const value=Number(input[key]??0);if(!Number.isFinite(value)||value<0||value>1e12)throw new Error("数值不正确");result[key]=Math.round(value*100)/100}return result}
export default {async fetch(request,env){const url=new URL(request.url);if(url.pathname==="/api/me"){const current=user(request);return current?json({user:current}):json({error:"请先登录"},401)}if(url.pathname==="/api/snapshots"){const current=user(request);if(!current)return json({error:"请先登录"},401);try{if(request.method==="GET"){const rows=await env.DB.prepare("SELECT id, month, data, created_at AS createdAt, updated_at AS updatedAt FROM financial_snapshots WHERE user_id = ? ORDER BY month DESC LIMIT 36").bind(current.id).all();return json({snapshots:(rows.results||[]).map(row=>({...row,data:JSON.parse(row.data)}))})}if(request.method==="POST"){const body=await request.json();if(!/^\d{4}-(0[1-9]|1[0-2])$/.test(body.month||""))return json({error:"月份格式不正确"},400);const data=cleanData(body.data),now=new Date().toISOString(),id=crypto.randomUUID();await env.DB.prepare("INSERT INTO financial_snapshots (id,user_id,month,data,updated_at) VALUES (?,?,?,?,?) ON CONFLICT(user_id,month) DO UPDATE SET data=excluded.data, updated_at=excluded.updated_at").bind(id,current.id,body.month,JSON.stringify(data),now).run();const row=await env.DB.prepare("SELECT id, month, data, created_at AS createdAt, updated_at AS updatedAt FROM financial_snapshots WHERE user_id=? AND month=?").bind(current.id,body.month).first();return json({snapshot:{...row,data:JSON.parse(row.data)}})}return json({error:"不支持的请求"},405)}catch(error){return json({error:error instanceof Error?error.message:"服务器暂时不可用"},500)}}return env.ASSETS.fetch(request)}};
